import Navagation from "@/components/Navagation";
import request from "@/utils/request";
export default {
  name: "Front",

  data() {
    return {
      user: {},
      role: 'user',
      loginStatus: false
    };
  },

  methods: {
    getUser() {
      let username = localStorage.getItem("user") ? JSON.parse(localStorage.getItem("user")).username : "";

      if (username) {
        // 从后台获取User数据
        this.request.get("/userinfo/" + username).then(res => {
          // 重新赋值后台的最新User数据
          this.user = res.data;
        });
      }
    }

  },
  components: {
    Navagation
  },

  created() {
    let stored = localStorage.getItem("user");

    if (stored) {
      let parsedUser = JSON.parse(stored);
      this.user = parsedUser;
      this.loginStatus = true; // 立即从 localStorage 的 UserDTO 中读取 role（登录接口已返回 role）

      if (parsedUser.role) {
        this.role = parsedUser.role;
        console.log('从 localStorage 读取到 role:', this.role);
      } else {
        console.warn('localStorage 中未找到 role 字段');
      } // 异步向后端确认角色（作为二次校验，不依赖此结果做首次渲染）


      request.post("/role").then(res => {
        if (res.code === '200') {
          this.role = res.data;
          console.log('从后端 /role 接口获取到 role:', this.role);
          this.getUser();
        } // 非200时不清除登录态，保留 localStorage 中的角色

      }).catch(error => {
        console.error('获取 role 失败:', error); // 网络异常时保留 localStorage 中的状态
      });
    } else {
      this.user = {
        nickname: '您未登录',
        avatarUrl: null
      };
      this.loginStatus = false;
    }
  }

};
